export class ClassifiedActionError extends Error {
    code;
    category;
    retryable;
    constructor(message, identity, options) {
        super(message, options);
        this.name = new.target.name;
        this.code = identity.code;
        this.category = identity.category;
        this.retryable = identity.retryable;
    }
}
export function isClassifiedActionError(error) {
    return error instanceof ClassifiedActionError;
}
export class ActionConfigurationError extends ClassifiedActionError {
    constructor(message, options) {
        super(message, { code: "ACTION_CONFIGURATION", category: "configuration", retryable: false }, options);
    }
}
export class PolicyDeniedError extends ClassifiedActionError {
    constructor(message, options) {
        super(message, { code: "POLICY_DENIED", category: "policy", retryable: false }, options);
    }
}
export class EventRoutingError extends ClassifiedActionError {
    constructor(message, options) {
        super(message, { code: "EVENT_ROUTING_FAILED", category: "domain", retryable: false }, options);
    }
}
export class OperationContextError extends ClassifiedActionError {
    constructor(message, options) {
        super(message, { code: "OPERATION_CONTEXT_INVALID", category: "domain", retryable: false }, options);
    }
}
